import { ref, onMounted, nextTick } from 'vue';
import axios from 'axios';
import { ElMessage } from 'element-plus';
import DockerContainers from "@/components/Container/DockerContainers.vue";
export default {
  __name: 'AddPlanDialog',
  setup(__props, {
    expose: __expose
  }) {
    const dialogVisible = ref(false);
    const formRef = ref(null);
    const form = ref({
      id: null,
      name: null,
      type: null,
      size: null,
      time: null,
      num: null,
      velocity: null,
      container1: null,
      container2: null,
      container2Ip: null
    });
    const rules = {
      name: [{
        required: true,
        message: '请输入名称',
        trigger: 'manual'
      }],
      type: [{
        required: true,
        message: '请选择类型',
        trigger: 'manual'
      }],
      container1: [{
        required: true,
        message: '请选择容器1',
        trigger: 'manual'
      }],
      container2: [{
        required: true,
        message: '请选择容器2',
        trigger: 'manual'
      }],
      container2Ip: [{
        required: true,
        message: '请输入容器2 IP',
        trigger: 'manual'
      }],
      size: [{
        required: true,
        message: '请输入大小',
        trigger: 'manual'
      }],
      time: [{
        required: true,
        message: '请输入时间',
        trigger: 'manual'
      }],
      num: [{
        required: true,
        message: '请输入数量',
        trigger: 'manual'
      }],
      velocity: [{
        required: true,
        message: '请输入速度',
        trigger: 'manual'
      }]
    };

    // 容器列表（用于下拉选择）
    const containers = ref([]);
    const containersRef = ref(null); // 引用容器组件

    const fetchContainers = async () => {
      try {
        await nextTick();
        if (containersRef.value) {
          await containersRef.value.fetchContainers();
          containers.value = containersRef.value.containers || [];
        }
      } catch (err) {
        console.error('获取容器列表失败', err);
      }
    };
    onMounted(() => {
      fetchContainers();
    });
    const openDialog = () => {
      dialogVisible.value = true;
      fetchContainers();
    };
    __expose({
      openDialog
    });
    const handleTypeChange = () => {
      form.value.size = null;
      form.value.time = null;
      form.value.num = null;
      form.value.velocity = null;
      form.value.container1 = null;
      form.value.container2 = null;
      form.value.container2Ip = null;
    };
    const submitForm = () => {
      formRef.value.validate(async valid => {
        if (valid) {
          try {
            const response = await axios.post('http://localhost:8081/plan/add', form.value);
            if (response.data === '添加成功') {
              ElMessage.success('添加成功');
              dialogVisible.value = false;
            } else {
              ElMessage.warning(response.data);
            }
          } catch (error) {
            ElMessage.error('添加失败');
            console.error(error);
          }
        }
      });
    };
    const __returned__ = {
      dialogVisible,
      formRef,
      form,
      rules,
      containers,
      containersRef,
      fetchContainers,
      openDialog,
      handleTypeChange,
      submitForm,
      ref,
      onMounted,
      nextTick,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      },
      DockerContainers
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
